"""🖼️ Figurinhas das palavras difíceis do 4º bimestre de 2027 (6º ao 9º ano), 21/11/2026. Desenhos em linha clara
feitos pelo Claude. Importado por termos.py. Sem fotos de pessoas e sem logos (marcas e órgãos aparecem só pelo nome escrito)."""
from linha_clara import V, K, t, r, c, p, etiqueta, seta_grossa
from termos_2027_1bim import kj, cel, blk, emo


def registrar(d, D, kp):
    pulados = []
    def dd(nomes, rot, corpo, cor="cinza"):
        novos = [n for n in nomes.split("|") if kp(n) not in D and kj(n) not in D]
        pulados.extend(n for n in nomes.split("|") if n not in novos)
        if not novos: return
        d("|".join(novos), rot, corpo, cor)
        for n in novos: D[kj(n)] = D[kp(n)]
    registrar.pulados = pulados
    E1 = lambda e, lab, cor="azul": emo(160, 100, e, 72) + etiqueta(160, 172, lab, cor, 12)
    E2 = lambda e1, e2, lab, cor="azul": emo(80, 100, e1, 56) + seta_grossa(120, 100, 196, cor, 24) + emo(242, 100, e2, 56) + etiqueta(160, 172, lab, cor, 12)
    EE = lambda es, lab, cor="azul": "".join(emo(160 + (i - (len(es) - 1) / 2) * 70, 100, e, 48) for i, e in enumerate(es)) + etiqueta(160, 172, lab, cor, 12)
    CARD = lambda linhas, e, cor="azul": r(50, 30, 220, 118, "#fff", rx=10, lw=3, sombra=3) + "".join(t(160, 62 + i * 26, s, 15, K, 900 if i == 0 else 700) for i, s in enumerate(linhas)) + emo(250, 150, e, 34)
    BAR = lambda url, e, cor="verde": r(30, 70, 260, 44, "#fff", rx=22, lw=3, sombra=3) + t(160, 99, url, 15, K, 800) + emo(160, 160, e, 34)
    SN = lambda e, sim, nao: emo(160, 70, e, 48) + r(50, 112, 100, 40, "#dcfce7", rx=8, lw=3) + t(100, 138, sim, 13, "verde", 900) + r(170, 112, 100, 40, "#fee2e2", rx=8, lw=3) + t(220, 138, nao, 13, "vermelho", 900)

    # ---------- 6º ano · redes, bits, arquivos, consumo ----------
    dd("destino", "Destino: para onde o pacote vai", E2("📦", "📬", "para onde vai", "azul"), "azul")
    dd("origem", "Origem: de onde o pacote saiu", E2("📮", "📦", "de onde saiu", "azul"), "azul")
    dd("numero de ordem|número de ordem", "Número de ordem: a posição de cada pedaço (1, 2, 3…)", "".join(cel(60 + i * 70, 70, str(i + 1), "#fff", 56, 50, 22) for i in range(3)) + etiqueta(160, 160, "a posição do pedaço", "azul", 12), "azul")
    dd("remontar", "Remontar: juntar os pedaços de novo, na ordem", EE(["🧩", "🧩", "🖼️"], "juntar de novo", "verde"), "verde")
    dd("reenviar", "Reenviar: mandar de novo só o pedaço que se perdeu", E2("❓", "🔁", "manda de novo", "amarelo"), "amarelo")
    dd("binario|binário", "Binário: o sistema que usa só 0 e 1", "".join(cel(26 + i * 46, 70, s, "#fff", 40, 44, 20) for i, s in enumerate("101100")) + etiqueta(160, 160, "só 0 e 1", "roxo", 12), "roxo")
    dd("kb", "KB (quilobyte): cerca de mil bytes, um texto curto", CARD(["KB", "≈ mil bytes"], "📄"), "azul")
    dd("mb", "MB (megabyte): cerca de mil KB, uma foto do celular", CARD(["MB", "≈ mil KB"], "🖼️"), "azul")
    dd("gb", "GB (gigabyte): cerca de mil MB, um filme", CARD(["GB", "≈ mil MB"], "🎬"), "azul")
    dd("tb", "TB (terabyte): cerca de mil GB, um HD grande", CARD(["TB", "≈ mil GB"], "🗄️"), "azul")
    dd("kb, mb e gb|mb e gb|kb, mb, gb", "KB, MB e GB: medidas do tamanho dos arquivos, do menor para o maior", "".join(r(60 + i * 70, 140 - (i + 1) * 30, 56, (i + 1) * 30, V["azul"][1], rx=4, lw=3) + t(88 + i * 70, 160, s, 15, K, 900) for i, s in enumerate(("KB", "MB", "GB"))), "azul")
    dd("compactar", "Compactar: diminuir e juntar arquivos num .zip", E2("📄", "🗜️", "vira .zip", "roxo"), "roxo")
    dd("descompactar", "Descompactar (extrair): tirar os arquivos de dentro do .zip", E2("🗜️", "📄", "tira do .zip", "roxo"), "roxo")
    dd("subpasta|subpastas", "Subpasta: uma pasta dentro de outra pasta", r(60, 40, 200, 120, V["amarelo"][1], rx=8, lw=3, sombra=3) + r(130, 80, 110, 66, V["amarelo"][0], rx=6, lw=3) + t(110, 68, "Fotos", 14, K, 900) + t(185, 118, "2027", 14, K, 900), "amarelo")
    dd("data de modificacao|data de modificação", "Data de modificação: o dia em que o arquivo foi mudado pela última vez", CARD(["✏️ Modificado em", "15/09/2027"], "📅"), "azul")
    dd("obsolescencia|obsolescência", "Obsolescência: o aparelho fica “velho” antes da hora", E2("📱", "🗑️", "velho antes da hora", "vermelho"), "vermelho")
    dd("consumo consciente", "Consumo consciente: comprar pensando no bolso, no planeta e no que você precisa", EE(["💰", "🌍", "🤔"], "bolso, planeta, necessidade", "verde"), "verde")
    dd("necessidade", "Necessidade: o que você precisa de verdade", SN("📱", "preciso", "só quero"), "verde")
    dd("desejo", "Desejo: o que você só quer, sem precisar", SN("✨", "preciso", "só quero"), "amarelo")
    dd("pelicula|película", "Película: a capinha fina que protege a tela", r(110, 30, 100, 150, "#e5e7eb", rx=14, lw=3) + r(116, 40, 88, 128, "#bfdbfe", rx=8, lw=2) + etiqueta(160, 182, "protege a tela", "azul", 12), "azul")
    dd("consertar", "Consertar: arrumar o que quebrou", E2("📱", "🔧", "arrumar", "verde"), "verde")
    dd("contaminar", "Contaminar: sujar o solo e a água com substâncias que fazem mal", E2("🔋", "💧", "suja a água", "vermelho"), "vermelho")
    dd("toxico|tóxico", "Tóxico: que faz mal à saúde", E1("☠️", "faz mal", "vermelho"), "vermelho")
    dd("reciclagem", "Reciclagem: transformar o material usado em matéria-prima de novo", E2("📱", "♻️", "volta a ser usado", "verde"), "verde")
    dd("etica|ética", "Ética: agir com respeito e pensar no que é certo", E1("🤝", "respeito", "verde"), "verde")
    dd("combinado|combinados", "Combinado: regra que o grupo aceitou junto", CARD(["Combinados", "✔ respeito", "✔ horário"], "📋"), "verde")
    dd("repassar", "Repassar: mandar para outras pessoas o que recebeu", E2("📲", "📲", "manda adiante", "amarelo"), "amarelo")
    dd("moderacao|moderação", "Moderação: sem exagero", SN("🎤", "1 áudio", "10 áudios"), "amarelo")
    dd("original", "Original: o arquivo verdadeiro, de onde a cópia é feita", E2("📄", "📄", "original → cópia", "azul"), "azul")

    # ---------- 7º ano · descarte, produto digital, pixels, HTML ----------
    dd("aterro", "Aterro: lugar onde o lixo comum é enterrado", r(40, 110, 240, 50, "#a16207", rx=4, lw=3) + emo(160, 90, "🗑️", 44) + etiqueta(160, 176, "o lixo é enterrado", "amarelo", 12), "amarelo")
    dd("logistica reversa|logística reversa", "Logística reversa: o produto faz o caminho de volta (consumidor → loja → fabricante → reciclagem)", EE(["🧑", "🏪", "🏭", "♻️"], "o caminho de volta", "verde"), "verde")
    dd("consumidor", "Consumidor: quem compra e usa o produto", E1("🛒", "quem compra", "azul"), "azul")
    dd("mina|minas", "Mina: lugar de onde se tiram metais da terra", E1("⛏️", "tira metais da terra", "amarelo"), "amarelo")
    dd("metal|metais", "Metal: material como cobre, ouro e alumínio", EE(["🥇", "🔩"], "cobre, ouro, alumínio", "cinza"), "cinza")
    dd("conduzir", "Conduzir: deixar a eletricidade passar", E2("🔌", "⚡", "a eletricidade passa", "amarelo"), "amarelo")
    dd("litio|lítio", "Lítio: metal usado na bateria do celular", E1("🔋", "metal da bateria", "verde"), "verde")
    dd("placa", "Placa: a peça com circuitos que leva a eletricidade dentro do aparelho", r(60, 40, 200, 120, "#166534", rx=8, lw=3, sombra=3) + "".join(p(f"M{70 + i * 30} 60 V{110 + (i % 3) * 10} H{90 + i * 30}", "none", 3).replace('stroke="#1c1f22"', 'stroke="#fbbf24"') for i in range(6)), "verde")
    dd("mineracao urbana|mineração urbana", "Mineração urbana: tirar metais do lixo eletrônico em vez de abrir uma mina nova", E2("📱", "🥇", "metal do lixo", "verde"), "verde")
    dd("bateria estufada", "Bateria estufada: bateria inchada, que pode pegar fogo", r(100, 50, 120, 90, V["vermelho"][1], rx=40, lw=4) + emo(160, 100, "🔋", 40) + etiqueta(160, 172, "pode pegar fogo!", "vermelho", 12), "vermelho")
    dd("produto digital", "Produto digital: vídeo, podcast ou página feito no computador", EE(["🎬", "🎧", "🌐"], "feito no computador", "roxo"), "roxo")
    dd("podcast", "Podcast: programa só de áudio", E1("🎧", "só áudio", "roxo"), "roxo")
    dd("storyboard", "Storyboard: o roteiro em desenhos, um quadrinho por cena", "".join(r(30 + i * 90, 50, 80, 70, "#fff", rx=4, lw=3, sombra=2) + t(70 + i * 90, 92, s, 22) for i, s in enumerate(("📱", "🗑️", "♻️"))) + etiqueta(160, 160, "um quadrinho por cena", "roxo", 12), "roxo")
    dd("narrador", "Narrador: quem fala o texto do vídeo", E1("🎤", "quem fala", "roxo"), "roxo")
    dd("editor", "Editor: programa que junta, corta e monta o vídeo ou o áudio", r(40, 50, 240, 100, "#1f2937", rx=8, lw=3) + "".join(r(56 + i * 74, 110, 66, 24, ("#60a5fa", "#f472b6", "#34d399")[i], rx=4, lw=2) for i in range(3)) + emo(160, 80, "✂️", 26), "roxo")
    dd("importar", "Importar: trazer os arquivos para o editor", E2("📁", "🎞️", "traz para o editor", "azul"), "azul")
    dd("linha do tempo", "Linha do tempo: onde os trechos ficam em ordem no editor", "".join(r(30 + i * 90, 80, 84, 36, ("#60a5fa", "#f472b6", "#34d399")[i], rx=4, lw=2) + t(72 + i * 90, 104, f"cena {i + 1}", 13, K, 900) for i in range(3)) + seta_grossa(40, 150, 280, "azul", 18), "azul")
    dd("cortar", "Cortar: tirar os pedaços que sobram", E1("✂️", "tira o que sobra", "vermelho"), "vermelho")
    dd("exportar", "Exportar: salvar o trabalho pronto num arquivo (.mp4, .mp3)", E2("🎞️", "💾", "salva o .mp4", "verde"), "verde")
    dd("documentar", "Documentar: registrar como o trabalho foi feito", E1("📝", "registrar como fez", "azul"), "azul")
    dd("ficha tecnica|ficha técnica", "Ficha técnica: título, equipe, ferramentas, créditos e o que aprendemos", CARD(["Ficha técnica", "🎬 título  👥 equipe", "📚 créditos"], "📋"), "azul")
    dd("autorizacao|autorização", "Autorização: o “pode” de quem aparece ou de quem criou", SN("🙋", "pode", "não pode"), "verde")
    dd("licenca|licença", "Licença: diz como os outros podem usar a obra", CARD(["Licença", "CC BY: use com crédito"], "📜"), "verde")
    dd("mostra", "Mostra: apresentação dos trabalhos para a turma", E2("🎬", "👏", "apresentar à turma", "roxo"), "roxo")
    dd("plateia", "Plateia: quem assiste", EE(["🧑", "👩", "🧒"], "quem assiste", "azul"), "azul")
    dd("rubrica", "Rubrica: a lista do que vai ser avaliado", CARD(["Rubrica", "✅ mensagem  ⏱️ tempo", "📚 créditos"], "📏"), "verde")
    dd("criterio|critério|criterios", "Critério: cada item que a rubrica avalia", E1("☑️", "um item avaliado", "verde"), "verde")
    dd("feedback", "Feedback: algo bom + uma sugestão", CARD(["👍 algo bom", "💡 uma sugestão"], "💬"), "verde")
    dd("megapixel|megapixels", "Megapixel: um milhão de pixels", CARD(["12 MP", "12 milhões de pixels"], "📷"), "roxo")
    dd("rgb", "RGB: cada pixel mistura vermelho, verde e azul (de 0 a 255)", c(134, 72, 34, "#ef4444", 3) + c(186, 72, 34, "#22c55e", 3) + c(160, 114, 34, "#3b82f6", 3) + etiqueta(160, 172, "vermelho, verde, azul", "roxo", 12), "roxo")
    dd("resolucao|resolução", "Resolução: a quantidade de pixels da imagem", "".join(r(40 + i * 30, 50 + j * 30, 30, 30, ["#fde68a", "#93c5fd"][(i + j) % 2], rx=0, lw=1) for i in range(8) for j in range(4)) + etiqueta(160, 178, "mais pixels, mais detalhe", "roxo", 12), "roxo")
    dd("amostra|amostras", "Amostra: cada medida da onda do som (44.100 por segundo)", p("M30 100 C 60 40, 90 160, 120 100 S 180 40, 210 100 S 270 160, 290 100", "none", 4) + "".join(c(30 + i * 26, 100, 5, "#f472b6", 2) for i in range(11)) + etiqueta(160, 172, "medidas do som", "rosa", 12), "rosa")
    dd("digital", "Digital: transformado em números (0 e 1)", E2("🖼️", "🔢", "vira número", "azul"), "azul")
    dd("html", "HTML: a língua das páginas da internet", CARD(["<h1>Olá</h1>", "<p>texto</p>"], "🌐"), "azul")
    dd("tag|tags", "Tag: etiqueta do HTML entre < e >", CARD(["<p> … </p>", "abre … fecha"], "🏷️"), "azul")

    # ---------- 8º ano · dados e privacidade ----------
    dd("identificar", "Identificar: descobrir quem a pessoa é", E1("🔍", "descobrir quem é", "azul"), "azul")
    dd("cpf", "CPF: o número de documento de cada pessoa no Brasil", CARD(["CPF", "•••.•••.•••-••"], "📇"), "cinza")
    dd("privacidade", "Privacidade: o direito de decidir o que os outros sabem sobre você", E1("🔐", "você decide", "verde"), "verde")
